SELECT city, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN city = 'Berlin' THEN 1 END), 0), 2) AS rating_per_berlin, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN country = 'DE' THEN 1 END), 0), 2) AS rating_per_de, COUNT_IF(city = 'London') AS london_events, COUNT(*) AS cnt, MAX(rating) FILTER (WHERE country = 'JP') AS jp_max_rating FROM suppliers GROUP BY 1 HAVING ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN country = 'DE' THEN 1 END), 0), 2) > 0 ORDER BY london_events DESC NULLS LAST
